  "call-of-duty-black-ops-7": {"summary":"Call of Duty: Black Ops 7 is a first-person shooter set in 2035, co-developed by Treyarch and Raven Software. The game features three main modes: a cooperative campaign playable with up to four players or solo, multiplayer with 6v6 and 20v20 modes, and the round-based Zombies mode. Multiplayer features a perk system split into combat specialties, weapon prestige progression, and scorestreak rewards.","themes":["Action","Science fiction","Warfare"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["Xbox Series X|S","PS4","PC","PS5","Xbox One"],"stores":[{"label":"Steam","url":"https://store.steampowered.com/app/3606480"}],"media":["scyn2l","scyn2m","scyn2n","scyn2k","ar63aw","ar63au"],"trailer":{"id":"dZdRDyYGoQg","name":"Teaser"},"releaseDates":[{"platform":"Xbox One","date":"Oct 05, 2025"},{"platform":"Xbox Series X|S","date":"Oct 05, 2025"},{"platform":"PC","date":"Oct 05, 2025"},{"platform":"PS4","date":"Oct 05, 2025"},{"platform":"PS5","date":"Oct 05, 2025"}],"multiplayer":null,"engines":["IW Engine"],"perspectives":["First person"],"similar":["call-of-duty-modern-warfare","wolfenstein-youngblood"],"xbox":null,"nintendo":null,"playstation":null,"steam":{"appId":"3606480","url":"https://store.steampowered.com/app/3606480","price":69.99,"regularPrice":69.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
  "factorio": {"summary":"You will be mining resources, researching technologies, building infrastructure, automating production and fighting enemies. Use your imagination to design your factory, combine simple elements into ingenious structures, apply management skills to keep it working and finally protect it from the creatures who don't really like you.","themes":["Science fiction","Survival","Sandbox"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["Switch 2","PC","Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/store/products/factorio-switch/"},{"label":"Steam","url":"https://store.steampowered.com/app/427520"},{"label":"GOG","url":"https://www.gog.com/game/factorio"}],"media":["sct3fy","sct3fz","sct3ft","sct3fu","sct3fv","sct3fw"],"trailer":{"id":"KVvXv1Z6EY8","name":"Trailer"},"releaseDates":[{"platform":"PC","date":"Mar 10, 2013"},{"platform":"Switch","date":"Oct 28, 2022"},{"platform":"Switch 2","date":"Dec 22, 2025"}],"multiplayer":{"onlineMax":null,"onlineCoopMax":65535,"offlineCoopMax":null,"splitscreen":false,"campaignCoop":false},"engines":["Proprietary Engine"],"perspectives":["Bird view / Isometric"],"similar":[],"xbox":null,"nintendo":{"nsuid":"70010000056818","url":"https://www.nintendo.com/store/products/factorio-switch/","price":35,"regularPrice":35,"discounted":false,"currency":"USD","sizeGb":2.6,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition"]},"playstation":null,"steam":{"appId":"427520","url":"https://store.steampowered.com/app/427520","price":35,"regularPrice":35,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
