  "pokemon-violet": {"summary":"Catch, battle, and train Pokémon in the Paldea Region, a vast land filled with lakes, towering peaks, wastelands, small towns, and sprawling cities. Explore a wide-open world at your own pace and traverse land, water, and air by riding on a form-shifting Legendary Pokémon. Choose either Sprigatito, Fuecoco, or Quaxly, to be your first partner Pokémon before setting off on your journey through Paldea.","themes":["Action","Fantasy","Kids","Open world"],"gameModes":["Single player","Multiplayer"],"availability":["Switch 2","Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/store/products/pokemon-violet-switch/"}],"media":["scfv7v","scfv7w","scfv7x","scfv7y","ar3vl4"],"trailer":{"id":"MAmueMsFR1o","name":"Announcement Trailer"},"releaseDates":[{"platform":"Switch","date":"Nov 18, 2022"},{"platform":"Switch 2","date":"Jun 05, 2025"}],"multiplayer":null,"engines":[],"perspectives":["Third person"],"similar":["pokemon-shield","torchlight-iii","borderlands-3","pokemon-sword"],"xbox":null,"nintendo":{"nsuid":"70010000053971","url":"https://www.nintendo.com/store/products/pokemon-violet-switch/","price":59.99,"regularPrice":59.99,"discounted":false,"currency":"USD","sizeGb":10.1,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition","ROM Bundle","Physical Edition - US","Physical Edition + DLC - US"]},"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
  "ghost-of-yotei": {"summary":"The game takes place 300 years after Ghost of Tsushima. Set in the lands surrounding Mount Yōtei, a towering peak in the heart of Ezo, an area of Japan known as Hokkaido in present day. The area is outside the rule of Japan, and filled with sprawling grasslands, snowy tundras, and unexpected dangers.","themes":["Action","Historical","Stealth","Open world"],"gameModes":["Single player"],"availability":["PS5"],"stores":[{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/10003923"}],"media":["sctzwq","sctzwr","sctzws","sctzwt","sctzwu","sctzww"],"trailer":{"id":"7z7kqwuf0a8","name":"Announcement Trailer"},"releaseDates":[{"platform":"PS5","date":"Oct 02, 2025"}],"multiplayer":null,"engines":["Proprietary Engine"],"perspectives":["Third person"],"similar":["horizon-zero-dawn","ghost-of-tsushima","red-dead-redemption-2","god-of-war--1","the-witcher-3-wild-hunt","assassins-creed-odyssey","control"],"xbox":null,"nintendo":null,"playstation":{"productId":"UP9000-PPSA26344_00-GHOST2CE00000000","conceptId":"10003923","url":"https://store.playstation.com/en-us/product/UP9000-PPSA26344_00-GHOST2CE00000000","price":69.99,"regularPrice":69.99,"discounted":false,"currency":"USD","plusIncluded":false,"platforms":[],"editions":["Complete Edition"],"sizeGb":null},"steam":null,"gamePassTiers":null,"playtime":null},
