  "microsoft-flight-simulator": {"summary":"Microsoft Flight Simulator is the next generation of one of the most beloved simulation franchises. From light planes to wide-body jets, fly highly detailed and stunning aircraft in an incredibly realistic world. Create your flight plan and fly anywhere on the planet. Enjoy flying day or night and face realistic, challenging weather conditions.","themes":["Non-fiction"],"gameModes":["Single player","Multiplayer"],"availability":["Xbox Series X|S","PC"],"stores":[{"label":"Steam","url":"https://store.steampowered.com/app/1250410"}],"media":["sc6vzx","sc6vzr","sc6vzs","sc6vzt","sc6vzu","sc6vzv"],"trailer":{"id":"dU6dq3zhCxw","name":"Accolades Trailer"},"releaseDates":[{"platform":"PC","date":"Aug 17, 2020"},{"platform":"Xbox Series X|S","date":"Jul 27, 2021"}],"multiplayer":null,"engines":["Ftech X"],"perspectives":["First person","Third person","Virtual Reality"],"similar":["nba-2k19"],"xbox":{"productId":"9NXN8GF8N9HT","url":"https://www.xbox.com/en-US/games/store/_/9NXN8GF8N9HT","price":null,"msrp":null,"onSale":false,"currency":"USD","sizeGb":null,"editions":[],"optimizedFor":["Xbox Series X|S"],"compatibleWith":["Xbox Series X|S"],"capabilities":["Capability4k","CapabilityHDR","ConsoleGen9Optimized"]},"nintendo":null,"playstation":null,"steam":{"appId":"1250410","url":"https://store.steampowered.com/app/1250410","price":20.99,"regularPrice":59.99,"discounted":true,"discountPercent":65,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
