  "pizza-tower": {"summary":"Pizza Tower is a 2D platformer mainly inspired by Wario Land and Earthworm Jim. The game has over-the-top hand-drawn animations and music. You play as Peppino Spaghetti, a manic pizza man with many abilities like charging, super jumping and dashing. Peppino has to go up each floor of the tower by finding keys, saving toppins folks and getting as many points as possible!","themes":["Action","Comedy"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["PC","Switch"],"stores":[{"label":"Steam","url":"https://store.steampowered.com/app/2231450"},{"label":"Nintendo eShop","url":"https://www.nintendo.com/us/store/products/pizza-tower-switch/"}],"media":["sck9l6","sck9l7","sck9l4","sctaih","sck9l3","sck9l5"],"trailer":{"id":"Wlq6fFOqI28","name":"Release Date Trailer"},"releaseDates":[{"platform":"PC","date":"Jan 26, 2023"},{"platform":"Switch","date":"Aug 27, 2024"}],"multiplayer":null,"engines":["GameMaker: Studio"],"perspectives":["Side view"],"similar":["pikuniku","forgotton-anne","torchlight-iii"],"xbox":null,"nintendo":{"nsuid":"70010000074087","url":"https://www.nintendo.com/us/store/products/pizza-tower-switch/","price":19.99,"regularPrice":19.99,"discounted":false,"currency":"USD","sizeGb":1.1,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior may vary from Nintendo Switch.","editions":["Standard Edition"]},"playstation":null,"steam":{"appId":"2231450","url":"https://store.steampowered.com/app/2231450","price":19.99,"regularPrice":19.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
