  "splatoon-2": {"summary":"Splatoon 2 is a multiplayer third-person shooter in which players control characters known as Inklings and use colored ink to attack opponents and clear goals. Inklings can alternate between humanoid form, during which they can fire ink with their weapons, and squid form, which allows them to swim through ink of their own color in order to move quickly and replenish ink supplies.","themes":["Action","Science fiction"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/games/detail/splatoon-2-switch/"}],"media":["ymen8krfg8tw5b8tbtnj","sczzu3","sczzu7","sczzu8","sczzu9","dd7xejq12jnvv4ojbzjp"],"trailer":{"id":"qN4w5D2tzME","name":"Trailer"},"releaseDates":[{"platform":"Switch","date":"Jul 21, 2017"}],"multiplayer":{"onlineMax":8,"onlineCoopMax":4,"offlineCoopMax":null,"splitscreen":false,"campaignCoop":false},"engines":[],"perspectives":["Third person"],"similar":["borderlands-3","wolfenstein-youngblood","xenoblade-chronicles-2"],"xbox":null,"nintendo":{"nsuid":"70010000000529","url":"https://www.nintendo.com/games/detail/splatoon-2-switch/","price":59.99,"regularPrice":59.99,"discounted":false,"currency":"USD","sizeGb":6.1,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition","Physical Edition - US"]},"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
