  "marathon--2": {"summary":"A PvP-focused extraction shooter set on the mysterious planet of Tau Ceti IV, Marathon will see players inhabit the bodies of Runners, cybernetic mercenaries who have been designed to survive the planet’s harsh environments and explore the lost colony that once inhabited Tau Ceti’s surface. Players will engage solo or in crews of three, searching for mysterious alien artifacts, as well as for valuable loot and new weapons and gear that they can add to their collection.","themes":["Action","Science fiction"],"gameModes":["Multiplayer","Battle Royale"],"availability":["Xbox Series X|S","PC","PS5"],"stores":[{"label":"Steam","url":"https://store.steampowered.com/app/3065800/"},{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/10008864"},{"label":"Xbox Store","url":"https://www.xbox.com/en-us/games/store/marathon/9pb32dkqkzdq"}],"media":["scmnfu","scmnfv","scmnfw","scmnfx","scmnfy","scmnfz"],"trailer":{"id":"wwH2aNBrq7c","name":"Announcement Trailer"},"releaseDates":[{"platform":"PC","date":"Mar 05, 2026"},{"platform":"PS5","date":"Mar 05, 2026"},{"platform":"Xbox Series X|S","date":"Mar 05, 2026"}],"multiplayer":null,"engines":["Tiger"],"perspectives":["First person"],"similar":["cyberpunk-2077","wolfenstein-youngblood","gears-5","the-outer-worlds"],"xbox":null,"nintendo":null,"playstation":{"productId":"JP9200-PPSA24487_00-MARBUNDLE0000001","conceptId":"10008864","url":"https://store.playstation.com/en-us/product/JP9200-PPSA24487_00-MARBUNDLE0000001","price":39.99,"regularPrice":39.99,"discounted":false,"currency":"USD","plusIncluded":false,"platforms":[],"editions":["Standard Edition","Deluxe Edition","Deluxe Upgrade"],"sizeGb":null},"steam":{"appId":"3065800","url":"https://store.steampowered.com/app/3065800","price":39.99,"regularPrice":39.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
