  "world-of-goo": {"summary":"World of Goo is a multiple award winning physics based puzzle / construction game made entirely by two guys. Drag and drop living, squirming, talking, globs of goo to build structures, bridges, cannonballs, zeppelins, and giant tongues. The millions of Goo Balls that live in the beautiful World of Goo are curious to explore - but they don't know that they are in a game, or that they are extremely delicious. Congratulations, and good luck!","themes":["Comedy","Sandbox"],"gameModes":["Single player","Co-operative"],"availability":["PC","Switch"],"stores":[{"label":"Steam","url":"https://store.steampowered.com/app/22000"},{"label":"Nintendo eShop","url":"https://www.nintendo.com/games/detail/world-of-goo-switch/"},{"label":"GOG","url":"https://www.gog.com/game/world_of_goo"},{"label":"Epic Games","url":"https://www.epicgames.com/store/en-US/product/world-of-goo/home"}],"media":["yc7qssyvyl7uicnez3hr","nt1x7lvbhtbopa63awps","dtne1q6owscdwa4ueux4","cuu6u3m3iw2jiehsecnp","szyqfcwqwwy3f12y2ykb","arf9u3bwn804gb0nwgvr"],"trailer":{"id":"uiCm88Me_3U","name":"Trailer"},"releaseDates":[{"platform":"PC","date":"Oct 13, 2008"},{"platform":"Switch","date":"Mar 16, 2017"}],"multiplayer":null,"engines":[],"perspectives":["Side view"],"similar":["human-fall-flat","hello-neighbor","limbo"],"xbox":null,"nintendo":{"nsuid":"70010000000165","url":"https://www.nintendo.com/games/detail/world-of-goo-switch/","price":14.99,"regularPrice":14.99,"discounted":false,"currency":"USD","sizeGb":0.1,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition"]},"playstation":null,"steam":{"appId":"22000","url":"https://store.steampowered.com/app/22000","price":14.99,"regularPrice":14.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
  "call-of-juarez-gunslinger": {"summary":"From the dust of a gold mine to the dirt of a saloon, Call of Juarez: Gunslinger is a real homage to the Wild West tales. Live the epic and violent journey of a ruthless bounty hunter on the trail of the West’s most notorious outlaws. Blurring the lines between man and myth, this adventure made of memorable encounters unveils the untold truth behind some of the greatest legends of the Old West.","themes":["Action","Fantasy","Historical","Comedy"],"gameModes":["Single player"],"availability":["PC","Switch"],"stores":[{"label":"GOG","url":"https://www.gog.com/game/call_of_juarez_gunslinger"},{"label":"Steam","url":"https://store.steampowered.com/app/204450"},{"label":"Nintendo eShop","url":"https://www.nintendo.com/games/detail/call-of-juarez-gunslinger-switch/"},{"label":"Xbox Store","url":"https://www.xbox.com/en-us/games/store/call-of-juarez-gunslinger/BT7M0N12GN51"}],"media":["ei7d33cdykjxb8glmxld","ngangtr4oahqej0pcrke","njp4204gewcfudiypxhe","t65h9qqsrfcgeduljnfd","jz4r1f7ve1jvnkj3kcms","ar88s"],"trailer":{"id":"Hbl5hCDFoxU","name":"Trailer"},"releaseDates":[{"platform":"PC","date":"May 22, 2013"},{"platform":"Switch","date":"Dec 09, 2019"}],"multiplayer":null,"engines":["Chrome Engine"],"perspectives":["First person"],"similar":[],"xbox":null,"nintendo":{"nsuid":"70010000014168","url":"https://www.nintendo.com/games/detail/call-of-juarez-gunslinger-switch/","price":19.99,"regularPrice":19.99,"discounted":false,"currency":"USD","sizeGb":2.7,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition"]},"playstation":null,"steam":{"appId":"204450","url":"https://store.steampowered.com/app/204450","price":14.99,"regularPrice":14.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
