  "steamworld-heist": {"summary":"Join Captain Piper Faraday, smuggler and occasional pirate, as she recruits a rag-tag team of steam-driven robots and sets out on a daring adventure. With your hearty crew you’ll board, loot and shoot your way through enemy spaceships. Overcome the challenges of the vast frontier by upgrading your robots with unique abilities, weapons – and even stylish hats!","themes":["Action","Science fiction"],"gameModes":["Single player"],"availability":["PS4","PC","Xbox One","Switch"],"stores":[{"label":"GOG","url":"https://www.gog.com/game/steamworld_heist"},{"label":"Nintendo eShop","url":"https://www.nintendo.com/games/detail/steamworld-heist-3ds/"},{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/204200"},{"label":"Steam","url":"https://store.steampowered.com/app/322190"}],"media":["ypafpze7qpyiua4euqkd","sjbh4vrz2nggx6cpssyx","lfhnggvmpsbkjkzzgteq","nhilamj0sxirlnstt5hy","jzy8qc3ahtkvseabak73","jxjfwnucmm9kll5sgamx"],"trailer":{"id":"epv2WLrWpXU","name":"Trailer"},"releaseDates":[{"platform":"PC","date":"Jun 07, 2016"},{"platform":"PS4","date":"Jun 07, 2016"},{"platform":"Switch","date":"Jul 12, 2018"},{"platform":"Xbox One","date":"TBD"}],"multiplayer":null,"engines":["sdl2"],"perspectives":["Side view"],"similar":["transistor","momodora-reverie-under-the-moonlight","battle-brothers","children-of-morta"],"xbox":null,"nintendo":null,"playstation":{"productId":"UP4473-CUSA01495_00-STEAMWORLDHEIST0","conceptId":"204200","url":"https://store.playstation.com/en-us/product/UP4473-CUSA01495_00-STEAMWORLDHEIST0","price":2.99,"regularPrice":14.99,"discounted":true,"currency":"USD","plusIncluded":false,"platforms":[],"editions":[],"sizeGb":null},"steam":{"appId":"322190","url":"https://store.steampowered.com/app/322190","price":14.99,"regularPrice":14.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
